const resourceVideos=[{id:'uhuol3I_8dc',title:'Wallaby Spreader · field film',duration:'24 seconds',image:'action.jpg',copy:'See an Australian-made Wallaby spreader working in the field.'},{id:'KALOOG6GbXw',title:'Wallaby Spreader · field clip',duration:'9 seconds',image:'spreader-23.jpg',copy:'A short look at the Wallaby in action from the Wal-Ag channel.'}];
const newsItems=[{id:'custom-built',title:'Custom-built spreaders',date:'16 June 2018',category:'PRODUCT NEWS',image:'news-custom.jpg',intro:'Different operations call for different configurations. Explore Wal-Ag’s approach to custom builds.',paragraphs:['A spreader may need to work in vineyard rows, around a particular access restriction or within a specialised operation. Wal-Ag’s published approach starts with the customer’s requirements, then works through the design.','Machines are manufactured to order. The team can discuss standard optional extras or a custom configuration, with any additional costs confirmed during the quotation process.','Options described in the original article include side delivery, seed or trace-element boxes, baffles, bridging bars, shrouds, dump valves, remote speed controls, mine-specific equipment and cameras.'],source:'https://www.spreaders.com.au/product-news/custom-built-spreaders/'},{id:'pto-vs-ground',title:'PTO versus ground-driven spreaders',date:'8 November 2016',category:'PRODUCT KNOWLEDGE',image:'news-pto.jpg',intro:'Understand the distinction between PTO-driven floor-chain control and ground-driven operation.',paragraphs:['A PTO-driven spreader takes power from the tractor’s power take-off. Wal-Ag explains that its floor-chain speed setting is independent of the tractor’s travel speed.','A ground-driven machine links its drive to forward movement. Changes in travel speed can therefore change material delivery.','The Wallaby range uses PTO drive. Talk to the team about material, application and operating conditions rather than choosing a machine on drive type alone.'],source:'https://www.spreaders.com.au/product-news/pto-versus-ground-driven-manure-spreaders/'},{id:'2018-tax-archive',title:'2018 instant asset write-off announcement',date:'17 June 2018',category:'HISTORICAL ARCHIVE',image:'news-archive.jpg',intro:'A dated company news item about a tax incentive discussed in June 2018.',paragraphs:['The original June 2018 announcement discussed an Australian small-business tax incentive and a then-upcoming end-of-financial-year deadline.','This item is retained as part of the company’s news archive. It does not describe current tax rules or eligibility. Refer to current official guidance and your adviser for present-day decisions.'],source:'https://www.spreaders.com.au/product-news/instant-asset-writeoff/'}];
function editorialCards(items){return `<div class="editorial-grid">${items.map(p=>`<a class="editorial-card reveal" href="${p.href}"><span>${p.label}</span><h3>${p.title}</h3><p>${p.copy}</p><i>↗</i></a>`).join('')}</div>`}
function expandedAboutPage(){return pageHead('ABOUT WAL-AG','A FAMILY BUSINESS.<br>AN ENGINEERING BACKGROUND.','Meet the Newcastle manufacturer behind the Wallaby Spreader.')+`<section class="wrap split"><img src="assets/about-real.jpg" alt="Company photography from Wal-Ag"><div><p class="eyebrow">OUR STORY</p><h2>PEOPLE BEHIND<br>THE PRODUCT.</h2><p>Wal-Ag manufactures the Wallaby Spreader in Newcastle. In 2016, the family-run business acquired Wallaby Fabrications after the previous owner retired.</p><p>The business brings engineering, design and fabrication experience across Australian industries. Its work spans standard spreader families, optional configurations and custom-build discussions.</p><p>Speak directly with the sales and technical team about the work you need to do and the equipment you already have.</p><div class="actions">${link('Talk to Wal-Ag','#/contact')}${link('Explore spreaders','#/products','outline')}</div></div></section><section class="pale-section"><div class="wrap"><p class="eyebrow">GET TO KNOW WAL-AG</p><h2>MORE THAN THE MACHINE.</h2>${editorialCards([{href:'#/difference',label:'01 / OUR APPROACH',title:'The Wal-Ag difference',copy:'Direct conversations, made-to-order equipment and a local workshop.'},{href:'#/why-wallaby',label:'02 / THE RANGE',title:'Why choose a Wallaby?',copy:'Construction, options and manufacturer support.'},{href:'#/order-process',label:'03 / NEXT STEPS',title:'The order process',copy:'From requirements to manufacturing and delivery discussions.'}])}</div></section>${cta()}`}
function differencePage(){return pageHead('THE WAL-AG DIFFERENCE','A BIG DECISION.<br>A PERSONAL APPROACH.','Talk through the details with the people who make your spreader.')+`<section class="wrap split"><div><p class="eyebrow">DIRECT FROM THE MANUFACTURER</p><h2>CONFIDENCE STARTS<br>WITH A CONVERSATION.</h2><p>Choosing machinery is a significant decision. Wal-Ag’s approach is to discuss the job, explain the options and work through questions before you commit.</p><p>The company manufactures in its Newcastle workshop. Ask about visiting, seeing a build or speaking with an existing owner about their experience.</p><p>Made-to-order equipment can have a different lead time from floor stock. Confirm the specification and current manufacturing arrangements with the team.</p>${link('Start the conversation','#/contact')}</div><img src="assets/difference.jpg" alt="Wal-Ag website photography about its manufacturing approach"></section><section class="pale-section"><div class="wrap">${editorialCards([{href:'#/products',label:'PRODUCTS',title:'Start with your work.',copy:'Explore capacities and custom builds without assuming suitability from size alone.'},{href:'#/faq',label:'ANSWERS',title:'Ask the practical questions.',copy:'Read about ownership, configuration and information to prepare.'},{href:'#/contact',label:'PEOPLE',title:'Talk directly.',copy:'Contact the sales and technical team about the details that matter to you.'}])}</div></section>${cta()}`}
function whyWallabyPage(){const features=[['Welded steel construction','The standard range uses an all-steel chassis, floor, hopper and spinners.'],['Purposeful hopper design','A wide floor and steep sides form part of the Wallaby’s material-handling design.'],['A versatile range','Discuss manure, seed, sawdust, lime, gypsum and topsoil applications.'],['Configuration options','Explore standard extras or speak with the team about custom fabrication.'],['Manufacturer contact','Talk directly about sales, technical questions and spare parts.'],['Ownership information','Use the operator guides and confirm maintenance and warranty details with Wal-Ag.']];return pageHead('WHY CHOOSE A WALLABY?','PRACTICAL DESIGN.<br>AUSTRALIAN MANUFACTURE.','The construction, flexibility and people behind the Wallaby range.')+`<section class="wrap"><div class="split"><img src="assets/why-wallaby.jpg" alt="Wal-Ag spreader imagery"><div><p class="eyebrow">THE WALLABY APPROACH</p><h2>BUILD A CLEARER<br>PICTURE OF YOUR NEXT MACHINE.</h2><p>The range combines PTO drive with steel construction and configuration options. Material, equipment and operating conditions should be discussed together.</p>${link('Compare the families','#/products')}</div></div><div class="benefit-grid">${features.map((x,i)=>`<article class="benefit-card reveal"><span>0${i+1}</span><h3>${x[0]}</h3><p>${x[1]}</p></article>`).join('')}</div></section>${cta()}`}
function faqPage(){return pageHead('FREQUENTLY ASKED QUESTIONS','PRACTICAL QUESTIONS.<br>CLEAR STARTING POINTS.','Answers adapted from Wal-Ag’s published FAQ. For your machine, consult the correct operator guide and the team.')+`<section class="wrap faq-layout"><aside class="resource-aside"><p class="eyebrow">OWNER RESOURCES</p><h3>Keep the right information close.</h3><a class="text-link" href="#/manuals">Manuals & downloads ↗</a><a class="text-link" href="#/contact">Ask Wal-Ag ↗</a><a class="text-link" href="#/products">Browse the range ↗</a></aside><div class="faq">${ownerFaqs.map(([q,a],i)=>`<details ${i===0?'open':''}><summary>${q}</summary><p>${a}${i===0||i===1||i===4?' <a class="inline-link" href="#/manuals">View manuals ↗</a>':''}</p></details>`).join('')}</div></section>${cta()}`}
function manualsPage(){const docs=[{title:'Wallaby Spreader operator instructions',image:'manual-spreader.jpg',file:'spreader-operator-instructions.pdf',type:'SPREADER / OPERATOR GUIDE',copy:'The original operator guide published by Wal-Ag.'},{title:'Side delivery conveyor instructions',image:'side-delivery.jpg',file:'side-delivery-operator-instructions.pdf',type:'ATTACHMENT / OPERATOR GUIDE',copy:'The original guide for the side delivery conveyor attachment.'},{title:'Wallaby product brochure',image:'spreader-10.jpg',file:'brochure.pdf',type:'RANGE / PRODUCT BROCHURE',copy:'Capacities, standard construction details and optional extras.'}];return pageHead('MANUALS & DOWNLOADS','THE DETAILS.<br>READY TO KEEP.','Download the operator documents and brochure available on Wal-Ag’s current site.')+`<section class="wrap"><div class="download-grid">${docs.map(d=>`<article class="download-card reveal"><img src="assets/${d.image}" alt="${d.title}" loading="lazy"><div><p class="eyebrow">${d.type}</p><h3>${d.title}</h3><p>${d.copy}</p><a class="button black" href="assets/${d.file}" target="_blank" rel="noopener">Open PDF <span>↗</span></a><a class="download-link" href="assets/${d.file}" download>Download copy ↓</a></div></article>`).join('')}</div><div class="notice">Use the guide applicable to your machine and attachment. Ask Wal-Ag to confirm the appropriate revision if you are unsure.</div></section>`}
function orderProcessPage(){return pageHead('OUR ORDER PROCESS','FROM YOUR REQUIREMENTS<br>TO YOUR WALLABY.','Agree the details with the business before manufacturing begins.')+`<section class="wrap"><div class="order-timeline">${[['01','Discuss the job','Talk through material, equipment, capacity interest and operating conditions.'],['02','Record the design requirements','The published process uses a detailed order form to capture the specification before the build.'],['03','Confirm the commercial arrangements','Agree the current quotation, deposit and payment stages directly with Wal-Ag.'],['04','Plan manufacturing','The team confirms scheduling after the order arrangements are completed.'],['05','Arrange completion and delivery','Confirm final payment and delivery responsibilities with the business.']].map(x=>`<article class="order-stage reveal"><span>${x[0]}</span><div><h3>${x[1]}</h3><p>${x[2]}</p></div></article>`).join('')}</div><div class="notice">Current prices, payment amounts, manufacturing dates and delivery arrangements require confirmation. The guided enquiry preview does not place an order.</div><div class="actions">${link('Prepare an enquiry','#/enquiry')}${link('Contact Wal-Ag','#/contact','outline')}</div></section>`}
function newsCards(){return `<div class="news-grid">${newsItems.map(n=>`<a class="news-card reveal" href="#/news/${n.id}"><img src="assets/${n.image}" alt="" loading="lazy"><div><span>${n.category} / ${n.date}</span><h3>${n.title}</h3><p>${n.intro}</p><b>Read article ↗</b></div></a>`).join('')}</div>`}
function newsPage(){return pageHead('NEWS & KNOWLEDGE','FROM THE<br>WAL-AG ARCHIVE.','Product stories and company articles, with their original publication dates retained.')+`<section class="wrap">${newsCards()}<div class="archive-note"><b>Looking for current offers?</b><p>The original site’s listed promotion ended in July 2018. View the dated archive or ask the team about present availability.</p>${link('Offers archive','#/offers','outline')}</div></section>`}
function articlePage(id){const n=newsItems.find(x=>x.id===id);if(!n)return newsPage();return pageHead(n.category,n.title.toUpperCase(),`Originally published ${n.date}.`)+`<article class="wrap article-layout"><img class="article-cover" src="assets/${n.image}" alt="Original Wal-Ag article imagery"><div class="article-body">${n.id==='2018-tax-archive'?'<div class="notice">Historical publication. This is not current tax guidance.</div>':''}${n.paragraphs.map(p=>`<p>${p}</p>`).join('')}<a class="text-link" href="${n.source}" target="_blank" rel="noopener">Read the original dated publication ↗</a><div class="actions">${link('More articles','#/news','outline')}${link('Discuss your requirements','#/contact')}</div></div></article>`}
function offersPage(){return pageHead('SPECIAL OFFERS / ARCHIVE','A DATED OFFER.<br>A USEFUL CONVERSATION.','The promotion published on the original website was a July 2018 offer, rather than a current advertised deal.')+`<section class="wrap split"><img src="assets/options.jpg" alt="Wallaby optional attachments"><div><p class="archive-badge">HISTORICAL / ENDED 31 JULY 2018</p><h2>2018 FINANCIAL-YEAR<br>BONUS OFFER.</h2><p>The original promotion offered a choice of a baffle plate or a CCTV camera with a qualifying new spreader order.</p><p>That deadline has passed. Contact Wal-Ag to ask about current pricing, options and any offers available now.</p><div class="actions">${link('Ask about current options','#/contact')}${link('Explore extras','#/product/custom','outline')}</div></div></section>`}
function videoCards(){return `<div class="video-grid">${resourceVideos.map(v=>`<article class="video-card reveal"><button class="video-thumb" data-film data-video="${v.id}" aria-label="Play ${v.title}"><img src="assets/${v.image}" alt="Wallaby spreader imagery" loading="lazy"><span>▶</span><small>${v.duration}</small></button><div><p class="eyebrow">FROM THE WAL-AG CHANNEL</p><h3>${v.title}</h3><p>${v.copy}</p><button class="text-link" data-film data-video="${v.id}">Play video ↗</button></div></article>`).join('')}</div>`}
function videosPage(){return pageHead('WALLABY IN ACTION','FROM THE WORKSHOP.<br>INTO THE FIELD.','Watch the two spreader films published on the Wal-Ag YouTube channel.')+`<section class="wrap">${videoCards()}<div class="actions"><a class="button outline" href="https://www.youtube.com/@wal-ag2771" target="_blank" rel="noopener">Visit the Wal-Ag channel <span>↗</span></a></div></section>`}
function contactPage(){return pageHead('CONTACT WAL-AG','TALK DIRECTLY<br>TO THE MANUFACTURER.','Discuss products, custom requirements, technical questions or a new enquiry with the Newcastle team.')+`<section class="wrap contact-layout"><div><p class="eyebrow">CONTACT DETAILS</p><div class="contact-block"><small>PHONE</small><a href="tel:1800306308">1800 306 308 ↗</a></div><div class="contact-block"><small>EMAIL</small><a href="mailto:sales@wal-ag.com.au">sales@wal-ag.com.au ↗</a></div><div class="contact-block"><small>ADDRESS</small><p>Unit 2, 17 Ironbark Close<br>Warabrook NSW</p></div></div><aside class="contact-enquiry"><p class="eyebrow">GET THE DETAILS TOGETHER</p><h2>START WITH<br>YOUR REQUIREMENTS.</h2><p>Use the four-step journey to prepare a brief. It keeps your answers in this browser and does not send a request.</p>${link('Prepare your enquiry','#/products','lime')}<p class="help">For a real submission, use the business’s existing contact page.</p><a class="text-link" href="https://www.spreaders.com.au/contact/" target="_blank" rel="noopener">Open the existing contact form ↗</a></aside></section>`}
function homeResources(){return `<section class="wrap"><div class="section-head reveal"><div><p class="eyebrow">MORE FROM WAL-AG</p><h2>ANSWERS, GUIDES<br>AND FIELD KNOWLEDGE.</h2></div><a class="text-link" href="#/manuals">All downloads ↗</a></div>${editorialCards([{href:'#/faq',label:'01 / FAQ',title:'Before you choose.',copy:'Practical answers about capacity, equipment, ownership and options.'},{href:'#/manuals',label:'02 / OWNER RESOURCES',title:'Keep the guides handy.',copy:'Spreader instructions, side-delivery instructions and the product brochure.'},{href:'#/videos',label:'03 / IN ACTION',title:'Watch the Wallaby.',copy:'Two original films from the Wal-Ag channel.'}])}</section><section class="pale-section"><div class="wrap"><div class="section-head"><div><p class="eyebrow">NEWS & KNOWLEDGE</p><h2>THE COMPANY ARCHIVE.</h2></div><a class="text-link" href="#/news">All articles ↗</a></div>${newsCards()}</div></section>`}
function backgroundVideoMarkup(){return `<div class="yt-surface" data-background-video="uhuol3I_8dc" data-paused="false" aria-hidden="true"></div>`}
let backgroundYoutubeAPI;
function loadBackgroundYoutubeAPI(){if(window.YT?.Player)return Promise.resolve(window.YT);if(backgroundYoutubeAPI)return backgroundYoutubeAPI;backgroundYoutubeAPI=new Promise(resolve=>{const previous=window.onYouTubeIframeAPIReady;window.onYouTubeIframeAPIReady=()=>{if(previous)previous();resolve(window.YT)};const script=document.createElement('script');script.src='https://www.youtube.com/iframe_api';script.async=true;script.onerror=()=>resolve(null);document.head.append(script);setTimeout(()=>resolve(window.YT?.Player?window.YT:null),15000)});return backgroundYoutubeAPI}
function wireBackgroundVideos(){document.querySelectorAll('[data-background-video]').forEach(surface=>{if(surface.dataset.bound)return;surface.dataset.bound='true';const section=surface.closest('section'),toggle=section.querySelector('[data-background-toggle]');let visible=false,player=null;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)surface.dataset.paused='true';const clear=()=>{surface.classList.remove('is-playing');if(player){try{player.destroy()}catch{}player=null}surface.replaceChildren()};const sync=()=>{const requested=visible&&surface.dataset.paused!=='true';if(requested&&!surface.querySelector('iframe')){const id=surface.dataset.backgroundVideo;surface.innerHTML=`<iframe title="Muted Wallaby field video" src="https://www.youtube-nocookie.com/embed/${id}?autoplay=1&mute=1&controls=0&loop=1&playlist=${id}&playsinline=1&rel=0&enablejsapi=1&origin=${encodeURIComponent(location.origin)}" allow="autoplay; encrypted-media" referrerpolicy="strict-origin-when-cross-origin" tabindex="-1"></iframe>`;const iframe=surface.querySelector('iframe');loadBackgroundYoutubeAPI().then(YT=>{if(!YT||!iframe.isConnected||surface.dataset.paused==='true'||!visible)return;player=new YT.Player(iframe,{events:{onReady:event=>{event.target.mute();event.target.playVideo()},onStateChange:event=>{if(event.data===1)surface.classList.add('is-playing');else if(event.data===0||event.data===2)surface.classList.remove('is-playing')},onError:()=>surface.classList.remove('is-playing')}})})}if(!requested)clear();if(toggle){toggle.textContent=surface.dataset.paused==='true'?'▶ Play background video':'Ⅱ Pause background video';toggle.setAttribute('aria-pressed',surface.dataset.paused!=='true')}};if(toggle)toggle.onclick=()=>{surface.dataset.paused=surface.dataset.paused==='true'?'false':'true';sync()};const observer=new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;sync()},{threshold:.15});observer.observe(surface);sync()})}
